message.content:
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?company ?label ?numEmployees WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?label ;
           sdk:hasNumberOfEmployees ?numEmployees .
  FILTER(CONTAINS(LCASE(STR(?label)), "steelworks"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?name WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?cert ;
                rdfs:label ?name .
  ?cert a sdk:ISO9001 .
  FILTER( langMatches(lang(?name),"en") || lang(?name) = "" )
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?naicsText WHERE {
  ?naics sdk:hasNAICSCodeValue ?code ;
         sdk:hasNAICSTextValue ?naicsText .
  FILTER(CONTAINS(STR(?code), "332996"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?naicsCode WHERE {
  ?naics sdk:hasNAICSTextValue ?text ;
         sdk:hasNAICSCodeValue ?naicsCode .
  FILTER(CONTAINS(UCASE(STR(?text)), "PIPE AND PIPE FITTING"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT DISTINCT ?cap ?label WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:hasMaterialCapability ?cap .
  ?cap rdfs:label ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "steel"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label ?descText WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                iof-core:describedBy ?desc .
  ?desc a sdk:BusinessDescription ;
        iof-scro:hasTextValue ?descText .
  FILTER(CONTAINS(?label, "Fabrication"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?stateName WHERE {
  ?city a sdk:City ;
        rdfs:label ?cityLabel ;
        sdk:locatedInState ?state .
  ?state a sdk:State ;
         rdfs:label ?stateName .
  FILTER(CONTAINS(?cityLabel, "San "))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?naicsCode WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:hasPrimaryNAICSClassifier ?naics .
  ?naics sdk:hasNAICSCodeValue ?naicsCode .
  FILTER(regex(str(?label), "Precision", "i"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?industry ?industryLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?mName ;
                sdk:suppliesToIndustry ?industry .
  ?industry rdfs:label ?industryLabel .
  FILTER(CONTAINS(LCASE(str(?mName)), "automation"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?product ?productLabel ?company ?companyLabel WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyLabel ;
           sdk:manufactures ?product .
  OPTIONAL { ?product rdfs:label ?productLabel . }
  FILTER(CONTAINS(LCASE(STR(?companyLabel)),"tooling"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?capability ?capLabel WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?label ;
           sdk:hasProcessCapability ?capability .
  ?capability rdfs:label ?capLabel .
  FILTER(CONTAINS(LCASE(?label), "aerospace"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?companyLabel ?cap ?capLabel
WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyLabel ;
           sdk:hasMaterialCapability ?cap .
  OPTIONAL { ?cap rdfs:label ?capLabel . }
  FILTER(CONTAINS(LCASE(STR(?companyLabel)), "metal"))
}
ORDER BY ?capLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?cert ?certLabel WHERE {
  ?man a iof-core:Manufacturer ;
       rdfs:label ?name ;
       sdk:hasCertificate ?cert .
  FILTER(CONTAINS(LCASE(STR(?name)), "plastics"))
  OPTIONAL { ?cert rdfs:label ?certLabel . }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?name ?state ?stateLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  FILTER(CONTAINS(LCASE(STR(?name)), "valve"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?lat ?lon
WHERE {
  ?company rdfs:label ?name ;
           sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coord .
  ?coord sdk:hasLatitudeValue ?lat ;
         sdk:hasLongitudeValue ?lon .
  FILTER(CONTAINS(LCASE(STR(?name)), "surface finish"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}
GROUP BY ?industry ?industryLabel
ORDER BY DESC(?manufacturerCount)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT ?naics ?naicsCode ?naicsText (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasPrimaryNAICSClassifier ?naics .
  OPTIONAL { ?naics sdk:hasNAICSCodeValue ?naicsCode . }
  OPTIONAL { ?naics sdk:hasNAICSTextValue ?naicsText . }
}
GROUP BY ?naics ?naicsCode ?naicsText
ORDER BY DESC(?manufacturerCount)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (COUNT(DISTINCT ?product) AS ?productCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label .
  OPTIONAL { ?manufacturer sdk:manufactures ?product . }
}
GROUP BY ?manufacturer ?label
ORDER BY DESC(?productCount)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (COUNT(DISTINCT ?cap) AS ?totalCapabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  OPTIONAL {
    ?manufacturer (sdk:hasProcessCapability|sdk:hasMaterialCapability) ?cap .
  }
}
GROUP BY ?manufacturer ?label
ORDER BY DESC(?totalCapabilities)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (COUNT(DISTINCT ?manufacturer) AS ?countWithoutBusinessDescription)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  FILTER NOT EXISTS { ?manufacturer iof-core:describedBy ?description . }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?cert .
  ?cert rdfs:label "ISO 9001" .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?ind1 , ?ind2 .
  ?ind1 a sdk:RenewableEnergyIndustry .
  ?ind2 a sdk:UtilitiesIndustry .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?name ?hasPrimaryNAICS ?naicsInst ?naicsCode ?naicsText WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name .
  FILTER(CONTAINS(LCASE(STR(?name)), "pipe"))
  OPTIONAL {
    ?manufacturer sdk:hasPrimaryNAICSClassifier ?naicsInst .
    OPTIONAL { ?naicsInst sdk:hasNAICSCodeValue ?naicsCode . }
    OPTIONAL { ?naicsInst sdk:hasNAICSTextValue ?naicsText . }
  }
  BIND(BOUND(?naicsInst) AS ?hasPrimaryNAICS)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?product ?label WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product .
  ?product rdfs:label ?label .
  FILTER(regex(str(?label), "Valve", "i"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK {
  ?man a iof-core:Manufacturer ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city rdfs:label ?cityLabel .
  FILTER regex(?cityLabel, "Portland", "i")
  FILTER NOT EXISTS { ?site sdk:hasZIPcode ?zip }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?lat ;
          sdk:hasLongitudeValue ?long .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?name WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                sdk:hasMaterialCapability ?matBronze , ?matSteel .
  ?matBronze a sdk:BronzeProcessingCapability .
  ?matSteel a sdk:SteelProcessingCapability .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT ?manufacturer
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  FILTER NOT EXISTS { ?manufacturer sdk:hasCertificate ?cert . }
}
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT ?manufacturer ?label ?descText WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label .
  FILTER(CONTAINS(LCASE(str(?label)), "coating"))
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?desc .
    ?desc a sdk:BusinessDescription ;
          iof-scro:hasTextValue ?descText .
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer ?label ?employees
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:hasNumberOfEmployees ?employeesRaw .
  BIND(xsd:integer(REPLACE(str(?employeesRaw), ",", "")) AS ?employees)
  FILTER(?employees > 500)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?name WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name .
  FILTER(regex(?name, "^A"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?naics ?text
WHERE {
  ?naics sdk:hasNAICSTextValue ?text .
  FILTER(regex(str(?text), "PIPE", "i"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer ?label WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasZIPcode ?zip .
  ?zip sdk:hasIntegerValue "85027.0" .
  OPTIONAL { ?manufacturer rdfs:label ?label }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?stateLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  FILTER(regex(?stateLabel, "^New "))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer ?label ?lat WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?lat .
  OPTIONAL { ?manufacturer rdfs:label ?label. }
  FILTER(xsd:double(?lat) > 45.0)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?industry ?industryType WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry ;
                rdfs:label ?manufacturerLabel .
  ?industry a ?industryType .
  FILTER(CONTAINS(LCASE(STR(?industryType)), "utilities"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?product ?productLabel ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product ;
                rdfs:label ?manufacturerLabel .
  ?product rdfs:label ?productLabel .
  FILTER(regex(?productLabel, "Pipe", "i"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?name WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name .
  FILTER(langMatches(lang(?name), "en"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer ?label (xsd:integer(REPLACE(str(?numStr), ",", "")) AS ?employeesNum)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasNumberOfEmployees ?numStr .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
}
ORDER BY DESC(?employeesNum)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?city ?cityLabel (COUNT(DISTINCT ?man) AS ?numManufacturers)
WHERE {
  ?man a iof-core:Manufacturer ;
       sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?cityLabel. }
}
GROUP BY ?city ?cityLabel
ORDER BY DESC(?numManufacturers)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel (COUNT(DISTINCT ?manufacturer) AS ?numManufacturers)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}
GROUP BY ?industry ?industryLabel
ORDER BY DESC(?numManufacturers)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?certificate ?label (COUNT(DISTINCT ?m) AS ?manufacturerCount)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:hasCertificate ?certificate .
  OPTIONAL { ?certificate rdfs:label ?label }
}
GROUP BY ?certificate ?label
ORDER BY DESC(?manufacturerCount)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?product ?productLabel (COUNT(DISTINCT ?manufacturer) AS ?numManufacturers)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product .
  ?product a iof-core:MaterialProduct .
  OPTIONAL { ?product rdfs:label ?productLabel }
}
GROUP BY ?product ?productLabel
ORDER BY DESC(?numManufacturers)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (COUNT(DISTINCT ?cap) AS ?numCapabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label. }
  {
    ?manufacturer sdk:hasProcessCapability ?cap .
  } UNION {
    ?manufacturer sdk:hasMaterialCapability ?cap .
  }
}
GROUP BY ?manufacturer ?label
ORDER BY DESC(?numCapabilities)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?naicsClassifier ?naicsText (COUNT(DISTINCT ?man) AS ?numManufacturers)
WHERE {
  ?man a iof-core:Manufacturer ;
       sdk:hasPrimaryNAICSClassifier ?naicsClassifier .
  OPTIONAL { ?naicsClassifier sdk:hasNAICSTextValue ?naicsText . }
}
GROUP BY ?naicsClassifier ?naicsText
ORDER BY DESC(?numManufacturers)
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?naicsText WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL {
    ?manufacturer sdk:hasPrimaryNAICSClassifier ?naics .
    ?naics sdk:hasNAICSTextValue ?naicsText .
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?zip WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    ?site sdk:hasZIPcode ?zipNode .
    ?zipNode sdk:hasIntegerValue ?zip .
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?name WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                sdk:hasProcessCapability ?cap .
  ?cap rdfs:label ?capLabel .
  FILTER(?capLabel = "Machining" || ?capLabel = "Coating")
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel (GROUP_CONCAT(DISTINCT ?capName; separator=", ") AS ?capabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  OPTIONAL {
    ?manufacturer (sdk:hasProcessCapability|sdk:hasMaterialCapability) ?cap .
    ?cap rdfs:label ?capName .
  }
}
GROUP BY ?manufacturer ?manufacturerLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?cityLabel ?stateLabel WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:locatedInCity ?city .
      OPTIONAL { ?city rdfs:label ?cityLabel . }
      OPTIONAL {
        ?city sdk:locatedInState ?stateViaCity .
        OPTIONAL { ?stateViaCity rdfs:label ?stateViaCityLabel . }
      }
    }
    OPTIONAL {
      ?site sdk:locatedInState ?stateViaSite .
      OPTIONAL { ?stateViaSite rdfs:label ?stateViaSiteLabel . }
    }
  }
  BIND(COALESCE(?stateViaCityLabel, ?stateViaSiteLabel) AS ?stateLabel)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:suppliesToIndustry ?industry .
  ?industry a ?industryType .
  FILTER(?industryType IN (sdk:RenewableEnergyIndustry, sdk:UtilitiesIndustry))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel (GROUP_CONCAT(DISTINCT ?itemLabel; SEPARATOR=", ") AS ?items)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel .
  {
    ?manufacturer sdk:manufactures ?prod .
    ?prod rdfs:label ?itemLabel .
  }
  UNION
  {
    ?manufacturer sdk:hasCertificate ?cert .
    ?cert rdfs:label ?itemLabel .
  }
}
GROUP BY ?manufacturer ?manufacturerLabel
ORDER BY ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?latitude ?longitude
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:hasSpatialCoordinates ?coords .
      OPTIONAL { ?coords sdk:hasLatitudeValue ?latitude. }
      OPTIONAL { ?coords sdk:hasLongitudeValue ?longitude. }
    }
  }
}
ORDER BY ?manufacturerLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?capability ?capLabel ?capabilityType WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  {
    ?manufacturer sdk:hasProcessCapability ?capability .
    ?capability rdfs:label ?capLabel .
    BIND("process" AS ?capabilityType)
  } UNION {
    ?manufacturer sdk:hasMaterialCapability ?capability .
    ?capability rdfs:label ?capLabel .
    BIND("material" AS ?capabilityType)
  }
}
ORDER BY ?manufacturer ?capability

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
