      ?m a iof-core:Manufacturer ;
         sdk:suppliesToIndustry ?industry .
    } GROUP BY ?industry
  }
  {
    SELECT (MAX(?count) AS ?maxCount) WHERE {
      {
        SELECT ?ind2 (COUNT(DISTINCT ?mm) AS ?count) WHERE {
          ?mm a iof-core:Manufacturer ;
              sdk:suppliesToIndustry ?ind2 .
        } GROUP BY ?ind2
      }
