  OPTIONAL { ?company rdfs:label ?companyLabel. }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel (COUNT(DISTINCT ?supplier) AS ?supplierCount)
WHERE {
  ?supplier a iof-core:Manufacturer ;
            sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}
GROUP BY ?industry ?industryLabel
ORDER BY DESC(?supplierCount)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer ?name ?employeesStr ?employees
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                sdk:hasNumberOfEmployees ?employeesStr .
  BIND(xsd:integer(REPLACE(str(?employeesStr), ",", "")) AS ?employees)
  FILTER(?employees >= 100)
}
ORDER BY DESC(?employees)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer ?label WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords a sdk:TwoDimensionalCartesianSpatialCoordinateDatum ;
          sdk:hasLatitudeValue ?lat ;
          sdk:hasLongitudeValue ?long .
  FILTER( xsd:decimal(?lat) = 0 && xsd:decimal(?long) = 0 )
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?label ?zipVal WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasZIPcode ?zip .
  ?zip sdk:hasIntegerValue ?zipVal .
  FILTER(regex(str(?zipVal), "^00000(\\.0)?$"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label ?descriptionText
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                iof-core:describedBy ?desc .
  ?desc iof-scro:hasTextValue ?descriptionText .
  OPTIONAL { ?manufacturer rdfs:label ?label. }
  FILTER( STRLEN(STR(?descriptionText)) > 20 )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?naicsCode ?naicsText
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:hasPrimaryNAICSClassifier ?naics .
  ?naics sdk:hasNAICSCodeValue ?naicsCode ;
         sdk:hasNAICSTextValue ?naicsText .
  FILTER(regex(str(?naicsCode), "332996"))
  FILTER(CONTAINS(UCASE(str(?naicsText)), "PIPE"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
}
GROUP BY ?manufacturer ?label
HAVING (COUNT(DISTINCT ?industry) = 2)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (COUNT(DISTINCT ?cap) AS ?capCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label }
  ?manufacturer (sdk:hasProcessCapability|sdk:hasMaterialCapability) ?cap .
  FILTER EXISTS { ?manufacturer sdk:hasProcessCapability ?procCap. }
  FILTER EXISTS { ?manufacturer sdk:hasMaterialCapability ?matCap. }
}
GROUP BY ?manufacturer ?label
HAVING (COUNT(DISTINCT ?cap) = 4)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:suppliesToIndustry ?industry .
  ?industry a ?itype .
  FILTER(?itype IN (sdk:RenewableEnergyIndustry, sdk:UtilitiesIndustry))
  FILTER NOT EXISTS {
    ?manufacturer sdk:suppliesToIndustry ?otherIndustry .
    ?otherIndustry a ?otherType .
    FILTER(?otherType NOT IN (sdk:RenewableEnergyIndustry, sdk:UtilitiesIndustry))
  }
}
GROUP BY ?manufacturer ?manufacturerLabel
HAVING (COUNT(DISTINCT ?industry) = 2 && COUNT(DISTINCT ?itype) = 2)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?org WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:suppliesToIndustry ?ind1 , ?ind2 .
  ?ind1 a sdk:RenewableEnergyIndustry .
  ?ind2 a sdk:UtilitiesIndustry .
  FILTER(?ind1 != ?ind2)
  FILTER NOT EXISTS {
    ?org sdk:suppliesToIndustry ?other .
    FILTER(?other != ?ind1 && ?other != ?ind2)
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?company ?companyLabel ?productCount WHERE {
  {
    SELECT ?company (COUNT(DISTINCT ?product) AS ?productCount) WHERE {
      ?company a iof-core:Manufacturer .
      ?company sdk:manufactures ?product .
    } GROUP BY ?company
  }
  {
    SELECT (MAX(?c) AS ?maxCount) WHERE {
      {
        SELECT ?comp (COUNT(DISTINCT ?prod) AS ?c) WHERE {
          ?comp a iof-core:Manufacturer .
          ?comp sdk:manufactures ?prod .
        } GROUP BY ?comp
      }
    }
  }
  FILTER(?productCount = ?maxCount)
  OPTIONAL { ?company rdfs:label ?companyLabel }
}
ORDER BY ?companyLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel ?num WHERE {
  {
    SELECT ?industry (COUNT(DISTINCT ?manu) AS ?num) WHERE {
      ?manu a iof-core:Manufacturer ;
            sdk:suppliesToIndustry ?industry .
    }
    GROUP BY ?industry
  }
  OPTIONAL { ?industry rdfs:label ?industryLabel. }
  {
    SELECT (MAX(?c) AS ?max) WHERE {
      {
        SELECT (COUNT(DISTINCT ?m) AS ?c) WHERE {
          ?m a iof-core:Manufacturer ;
             sdk:suppliesToIndustry ?ind .
        }
        GROUP BY ?ind
      }
    }
  }
  FILTER(?num = ?max)
}
ORDER BY DESC(?num)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?stateLabel ?org ?orgLabel ?headcountNum WHERE {
  {
    SELECT ?state (MAX(?hcNum) AS ?maxHeadcount) WHERE {
      ?org a iof-core:Manufacturer ;
           sdk:hasNumberOfEmployees ?hcStr ;
           sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      BIND(xsd:integer(REPLACE(STR(?hcStr), "[^0-9]", "")) AS ?hcNum)
    } GROUP BY ?state
  }
  ?org a iof-core:Manufacturer ;
       sdk:hasNumberOfEmployees ?hcStr ;
       sdk:organizationLocatedIn ?site ;
       rdfs:label ?orgLabel .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  BIND(xsd:integer(REPLACE(STR(?hcStr), "[^0-9]", "")) AS ?headcountNum)
  FILTER(?headcountNum = ?maxHeadcount)
}
ORDER BY ?stateLabel ?orgLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?company ?label (COUNT(DISTINCT ?cap) AS ?totalCapabilities)
WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?label .
  {
    ?company sdk:hasProcessCapability ?cap .
  }
  UNION
  {
    ?company sdk:hasMaterialCapability ?cap .
  }
}
GROUP BY ?company ?label
ORDER BY DESC(?totalCapabilities)
LIMIT 1

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer (CONCAT(COALESCE(?cityLabel, "Unknown"), ", ", COALESCE(?stateLabel, "Unknown")) AS ?locationString)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:locatedInCity ?city .
      ?city rdfs:label ?cityLabel .
      OPTIONAL {
        ?city sdk:locatedInState ?state .
        ?state rdfs:label ?stateLabel .
      }
    }
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
SELECT ?manufacturer ?manufacturerLabel ?siteCoordinates WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:hasSpatialCoordinates ?coords .
      OPTIONAL {
        ?coords sdk:hasLatitudeValue ?lat .
        ?coords sdk:hasLongitudeValue ?long .
      }
    }
  }
  BIND(
    IF(
      (BOUND(?lat) && BOUND(?long)),
      CONCAT(STR(?lat), ",", STR(?long)),
      "no-coords"
    ) AS ?siteCoordinates
  )
}
ORDER BY ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer (COALESCE(?zipValue, ?addrText, ?name) AS ?preferredValue)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?name. }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:hasZIPcode ?zipNode .
      ?zipNode sdk:hasIntegerValue ?zipValue .
    }
    OPTIONAL {
      ?site sdk:hasPostalAddress ?addrNode .
      ?addrNode iof-scro:hasTextValue ?addrText .
    }
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel (GROUP_CONCAT(DISTINCT ?capLabel; separator=", ") AS ?capabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel .
  OPTIONAL {
    ?manufacturer (sdk:hasProcessCapability|sdk:hasMaterialCapability) ?cap .
    ?cap rdfs:label ?capLabel .
  }
}
GROUP BY ?manufacturer ?manufacturerLabel
ORDER BY ?manufacturerLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manLabel .
  {
    ?manufacturer sdk:hasProcessCapability ?proc .
    ?proc rdfs:label ?procLabel .
    FILTER(regex(str(?procLabel), "ing$", "i"))
  }
  UNION
  {
    ?manufacturer sdk:hasMaterialCapability ?mat .
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?company ?companyLabel ?site ?city ?state ?stateName WHERE {
  ?company a iof-core:Manufacturer ;
           sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateName .
  OPTIONAL { ?company rdfs:label ?companyLabel . }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?state ?stateLabel WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }

  {
    # Path via site -> city -> state
    ?manufacturer sdk:organizationLocatedIn ?site .
    ?site sdk:locatedInCity ?city .
    ?city sdk:locatedInState ?state .
  }
  UNION
  {
    # Direct company -> state link
    ?manufacturer sdk:locatedInState ?state .
  }

  OPTIONAL { ?state rdfs:label ?stateLabel . }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel WHERE {
  ?manufacturer a iof-core:Manufacturer .
  ?manufacturer sdk:hasProcessCapability ?cap .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  FILTER NOT EXISTS {
    ?manufacturer sdk:hasProcessCapability ?cap2 .
    ?cap2 rdfs:label ?cap2Label .
    FILTER(!regex(?cap2Label, "ing$","i"))
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label .
  # has at least one Bronze or Steel capability
  ?manufacturer sdk:hasMaterialCapability ?matAllowed .
  ?matAllowed a ?allowedType .
  VALUES ?allowedType { sdk:BronzeProcessingCapability sdk:SteelProcessingCapability }

  # no material capability of a disallowed type
  FILTER NOT EXISTS {
    ?manufacturer sdk:hasMaterialCapability ?matOther .
    ?matOther a ?otherType .
    FILTER( ?otherType NOT IN (sdk:BronzeProcessingCapability, sdk:SteelProcessingCapability) )
  }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?site ?latitude ?longitude
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site a sdk:GeospatialLocation .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  OPTIONAL {
    ?site sdk:hasSpatialCoordinates ?coords .
    OPTIONAL { ?coords sdk:hasLatitudeValue ?latitude. }
    OPTIONAL { ?coords sdk:hasLongitudeValue ?longitude. }
  }
  FILTER ( !BOUND(?latitude) || !BOUND(?longitude) )
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label. }
  ?manufacturer sdk:hasCertificate ?cert .
  FILTER NOT EXISTS { ?manufacturer sdk:manufactures ?product. }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT DISTINCT ?manufacturer ?label ?text WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label. }
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?desc .
    OPTIONAL { ?desc iof-scro:hasTextValue ?text . }
  }
  FILTER(
    !bound(?desc)
    || !bound(?text)
    || str(?text) = ""
    || regex(str(?text), "^\\s*$")
  )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label. }
  FILTER NOT EXISTS {
    ?manufacturer sdk:suppliesToIndustry ?anyIndustry .
  }
}
ORDER BY ?label

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label ?zipVal WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasZIPcode ?zip .
  ?zip sdk:hasIntegerValue ?zipVal .

  FILTER (
    NOT EXISTS { ?site sdk:locatedInCity ?city }
    ||
    (
      EXISTS { ?site sdk:locatedInCity ?city }
      && NOT EXISTS { ?city sdk:locatedInState ?state }
    )
  )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label ?certCount WHERE {
  {
    SELECT (AVG(?c) AS ?avgCert) WHERE {
      SELECT ?m (COUNT(?cert) AS ?c) WHERE {
        ?m a iof-core:Manufacturer .
        OPTIONAL { ?m sdk:hasCertificate ?cert . }
      } GROUP BY ?m
    }
  }
  {
    SELECT ?manufacturer (COUNT(?cert) AS ?certCount) WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:hasCertificate ?cert . }
    } GROUP BY ?manufacturer
  }
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  FILTER(?certCount > ?avgCert)
}
ORDER BY DESC(?certCount)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?industry ?industryLabel ?manu ?manuLabel ?employees ?avgEmployees WHERE {
  ?manu a iof-core:Manufacturer ;
        sdk:suppliesToIndustry ?industry ;
        sdk:hasNumberOfEmployees ?empStr .
  BIND(xsd:integer(REPLACE(str(?empStr), ",", "")) AS ?employees)

  {
    SELECT ?industry (AVG(?empVal) AS ?avgEmployees) WHERE {
      ?m2 a iof-core:Manufacturer ;
          sdk:suppliesToIndustry ?industry ;
          sdk:hasNumberOfEmployees ?empStr2 .
      BIND(xsd:decimal(REPLACE(str(?empStr2), ",", "")) AS ?empVal)
    } GROUP BY ?industry
  }

  FILTER(?employees > ?avgEmployees)

  OPTIONAL { ?manu rdfs:label ?manuLabel }
  OPTIONAL { ?industry rdfs:label ?industryLabel }
}
ORDER BY ?industryLabel ?manuLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?stateLabel (AVG(?empNum) AS ?avgEmployees)
WHERE {
  {
    SELECT DISTINCT ?man ?state ?stateLabel ?empNum WHERE {
      ?man a iof-core:Manufacturer ;
           sdk:manufactures ?prod ;
           sdk:hasNumberOfEmployees ?empStr ;
           sdk:organizationLocatedIn ?site .
      ?prod rdfs:label ?prodLabel .
      FILTER(regex(str(?prodLabel), "[0-9]")) .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      ?state rdfs:label ?stateLabel .
      BIND(xsd:decimal(REPLACE(str(?empStr), ",", "")) AS ?empNum)
    }
  }
}
GROUP BY ?stateLabel
ORDER BY ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?stateLabel ?procCount ?matCount
WHERE {
  {
    SELECT ?state ?stateLabel (COUNT(DISTINCT ?procCap) AS ?procCount) (COUNT(DISTINCT ?matCap) AS ?matCount)
    WHERE {
      ?man a iof-core:Manufacturer ;
           sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      OPTIONAL { ?state rdfs:label ?stateLabel . }
      OPTIONAL { ?man sdk:hasProcessCapability ?procCap . }
      OPTIONAL { ?man sdk:hasMaterialCapability ?matCap . }
    }
    GROUP BY ?state ?stateLabel
  }
}
ORDER BY DESC(?procCount) DESC(?matCount)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?naicsCode ?naicsText ?numManufacturers ?numProducts ?avgEmployees
WHERE {
  {
    SELECT ?naics ?naicsCode ?naicsText (COUNT(DISTINCT ?manu) AS ?numManufacturers) (AVG(?empVal) AS ?avgEmployees)
    WHERE {
      ?manu a iof-core:Manufacturer ;
            sdk:hasPrimaryNAICSClassifier ?naics .
      ?naics sdk:hasNAICSCodeValue ?naicsCode ;
             sdk:hasNAICSTextValue ?naicsText .
      OPTIONAL {
        ?manu sdk:hasNumberOfEmployees ?empStr .
        BIND(xsd:decimal(REPLACE(STR(?empStr), ",", "")) AS ?empVal)
      }
    }
    GROUP BY ?naics ?naicsCode ?naicsText
  }
  OPTIONAL {
    SELECT ?naics (COUNT(DISTINCT ?product) AS ?numProducts)
    WHERE {
      ?manu2 a iof-core:Manufacturer ;
             sdk:hasPrimaryNAICSClassifier ?naics ;
             sdk:manufactures ?product .
    }
    GROUP BY ?naics
  }
}
ORDER BY ?naicsCode

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?name WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?name .
  FILTER( lang(?name) = "en" || lang(?name) = "" )
} ORDER BY ?company

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT DISTINCT ?manufacturer ?label ?descText WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label. }
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?desc .
    ?desc iof-scro:hasTextValue ?descText .
  }
  FILTER (
    regex(coalesce(str(?label), ""), "Company", "i") ||
    regex(coalesce(str(?descText), ""), "Company", "i")
  )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product ;
                rdfs:label ?manufacturerLabel .
  ?product a iof-core:MaterialProduct ;
           rdfs:label ?productLabel .
  FILTER(?productLabel IN ("Product 1","Product 2"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT DISTINCT ?company ?companyLabel ?employeesInt WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?companyLabel ;
           sdk:organizationLocatedIn ?site ;
           sdk:hasNumberOfEmployees ?employeesStr ;
           sdk:hasProcessCapability ?cap .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label "State A" .
  ?cap rdfs:label ?capLabel .
  BIND(xsd:integer(REPLACE(str(?employeesStr), "[^0-9]", "")) AS ?employeesInt)
  FILTER(?employeesInt >= 50)
  FILTER(regex(?capLabel, "ing$", "i"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cityLabel (AVG(xsd:decimal(REPLACE(?empStr, ",", ""))) AS ?avgEmployeeCount)
WHERE {
  {
    SELECT ?city ?empStr
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:organizationLocatedIn ?site ;
         sdk:hasNumberOfEmployees ?empStr .
      ?site sdk:locatedInCity ?city .
      ?m (sdk:hasProcessCapability|sdk:hasMaterialCapability) ?cap .
    }
    GROUP BY ?m ?city ?empStr
    HAVING (COUNT(DISTINCT ?cap) >= 4)
  }
  ?city rdfs:label ?cityLabel .
}
GROUP BY ?cityLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label ?zipVal ?lat WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site ;
                rdfs:label ?label .
  ?site sdk:hasZIPcode ?zip ;
        sdk:hasSpatialCoordinates ?coord .
  ?zip sdk:hasIntegerValue ?zipVal .
  ?coord sdk:hasLatitudeValue ?lat .
  FILTER( REPLACE(STR(?zipVal), "\\.0$", "") != "00000" )
  FILTER( xsd:decimal(?lat) > xsd:decimal(?1) )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product ;
                sdk:hasProcessCapability ?proc ;
                sdk:hasMaterialCapability ?mat .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
}
GROUP BY ?manufacturer ?manufacturerLabel
HAVING (
  COUNT(DISTINCT ?product) = 2 &&
  COUNT(DISTINCT ?proc) = 2 &&
  COUNT(DISTINCT ?mat) = 2
)
